package com.dawnrise.school.announcement;
import jakarta.validation.Valid;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/platform/releases") @PreAuthorize("@platformTokenSecurity.hasPermissions(authentication,'PLATFORM_RELEASE_PUBLISH')")
public class DawnriseReleaseController {private final DawnriseReleaseService service;public DawnriseReleaseController(DawnriseReleaseService service){this.service=service;}@PostMapping public ReleaseDtos.View create(JwtAuthenticationToken a,@Valid @RequestBody ReleaseDtos.Create r){return service.create(Long.parseLong(a.getName()),r);}@GetMapping("/{id}") public ReleaseDtos.View get(@PathVariable long id){return service.get(id);}@PostMapping("/{id}/publish") public ReleaseDtos.View publish(JwtAuthenticationToken a,@PathVariable long id,@Valid @RequestBody AnnouncementDtos.Version v){return service.publish(Long.parseLong(a.getName()),id,v.version());}@PostMapping("/{id}/cancel") public ReleaseDtos.View cancel(JwtAuthenticationToken a,@PathVariable long id,@Valid @RequestBody AnnouncementDtos.Version v){return service.cancel(Long.parseLong(a.getName()),id,v.version());}}
